class QuoteListComponentService {
    constructor() {
        this.quoteFacade = inject(QuoteFacade);
        this.translationService = inject(TranslationService);
        this.defaultSortOption = 'byCode';
        this.sort = new BehaviorSubject(this.defaultSortOption);
        this.currentPage = new BehaviorSubject(0);
        //TODO: temporary solution caused by gaps in the API. Refer to
        //https://jira.tools.sap/browse/CXEC-31715
        this.sortOptions = [
            { code: 'byDate' },
            { code: 'byCode' },
            { code: 'byName' },
            { code: 'byState' },
        ];
        this.quotesState$ = this.quoteFacade
            .getQuotesState({
            currentPage$: this.currentPage
                .asObservable()
                .pipe(distinctUntilChanged()),
            sort$: this.sort.asObservable().pipe(distinctUntilChanged()),
        })
            .pipe(tap((quotesState) => {
            if (quotesState.data?.sorts) {
                this.sortOptions = quotesState.data.sorts;
            }
        }));
        this.sortLabels$ = combineLatest([
            this.translationService.translate('sorting.date'),
            this.translationService.translate('quote.list.quoteId'),
            this.translationService.translate('quote.list.name'),
            this.translationService.translate('quote.list.status'),
        ]).pipe(map(([textByQuoteUpdatedDate, textByQuoteCode, textByQuoteName, textByQuoteStatus,]) => {
            return {
                byDate: textByQuoteUpdatedDate,
                byCode: textByQuoteCode,
                byName: textByQuoteName,
                byState: textByQuoteStatus,
            };
        }));
    }
    /**
     * Sets sorting for quote list.
     *
     * @param sort - Code of desired sort option that will be applied to the quote list
     */
    setSorting(sort) {
        this.sort.next(sort);
    }
    /**
     * Sets current page.
     *
     * @param page - number of page that will be applied to the quote list
     */
    setPage(page) {
        this.currentPage.next(page);
    }
    static { this.ɵfac = i0.ɵɵngDeclareFactory({ minVersion: "12.0.0", version: "21.2.9", ngImport: i0, type: QuoteListComponentService, deps: [], target: i0.ɵɵFactoryTarget.Injectable }); }
    static { this.ɵprov = i0.ɵɵngDeclareInjectable({ minVersion: "12.0.0", version: "21.2.9", ngImport: i0, type: QuoteListComponentService }); }
}
